function Parse-Rows([string]$Text, [bool]$IsArticle) {
    foreach ($line in ($Text -split "`r?`n")) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        $v = $line.Split('|')
        if ($v.Count -ne 12) { throw "Dòng dữ liệu không hợp lệ: $($v[0]) có $($v.Count) trường" }
        [pscustomobject]@{ Slug=$v[0]; Title=$v[1]; Description=$v[2]; Category=$v[3]; Image=$v[4]; Intro=$v[5]; Section=$v[6]; Detail=$v[7]; Steps=$v[8].Split(';'); Notes=$v[9].Split(';'); Question=$v[10]; Answer=$v[11]; IsArticle=$IsArticle }
    }
}

