    if ($html -notmatch 'id="seo-page-styles"') {
        $css = @'
<style id="seo-page-styles">.seo-page{padding:38px 0}.seo-article{color:#f4f4f4;line-height:1.78}.seo-article__header{text-align:center;max-width:900px;margin:0 auto 30px}.seo-article__label{display:inline-block;padding:5px 13px;border-radius:999px;background:#f9ad12;color:#17110a;font-weight:700;text-transform:uppercase;font-size:.78rem;letter-spacing:.04em}.seo-article h1{margin:14px 0 8px;color:#f9ad12;font-size:clamp(2rem,5vw,3.1rem);line-height:1.2}.seo-article__meta{margin:0 0 14px;color:#aaa;font-size:.9rem}.seo-article__lead{font-size:1.12rem;color:#e4e4e4}.seo-article__hero{margin:28px auto 36px;max-width:900px}.seo-article__hero img{width:100%;max-height:480px;object-fit:cover;border-radius:14px;border:1px solid rgba(249,173,18,.45)}.seo-article__hero figcaption{text-align:center;color:#aaa;font-size:.88rem;margin-top:8px}.seo-article section{margin:30px 0;padding:26px 28px;background:rgba(8,10,15,.78);border:1px solid rgba(249,173,18,.22);border-radius:12px}.seo-article h2{color:#f9ad12;font-size:1.65rem}.seo-article h3{color:#fff;font-size:1.18rem}.seo-checklist{margin:16px 0 0;padding-left:24px}.seo-checklist li{margin:8px 0}.seo-responsible{border-left:4px solid #f9ad12!important}.seo-article a{color:#f9ad12;text-decoration:underline}@media(max-width:549px){.seo-page{padding:24px 0}.seo-article section{padding:20px}.seo-article__lead{font-size:1rem}}</style>
'@
        $html = $html -replace '</head>', ($css + '</head>')
    }
    [IO.File]::WriteAllText($path, $html, $Utf8)
}

$newsPath = Join-Path $SiteDir 'tin-tuc.html'
$newsHtml = [IO.File]::ReadAllText($newsPath, [Text.Encoding]::UTF8)
$newsTitle = 'Tin tức 789Club: Hướng dẫn và kiến thức mới nhất'
$newsDescription = 'Tổng hợp bài viết 789Club về luật chơi, hướng dẫn, phân tích dữ liệu và nguyên tắc giải trí có trách nhiệm.'
$newsCanonical = $Domain + 'tin-tuc.html'
$newsImage = $Domain + 'assets/wp-content/uploads/2025/07/Bi-quyet-choi-tai-xiu-MD5.webp'
$newsHtml = [regex]::Replace($newsHtml, '(?is)<title>.*?</title>', '<title>' + (E $newsTitle) + '</title>', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+name=["'']description["''][^>]*>', '<meta name="description" content="' + (E $newsDescription) + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<link\s+rel=["'']canonical["''][^>]*>', '<link rel="canonical" href="' + $newsCanonical + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<link\s+rel=["'']next["''][^>]*>', '')
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+property=["'']og:type["''][^>]*>', '<meta property="og:type" content="website">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+property=["'']og:title["''][^>]*>', '<meta property="og:title" content="' + (E $newsTitle) + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+property=["'']og:description["''][^>]*>', '<meta property="og:description" content="' + (E $newsDescription) + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+property=["'']og:url["''][^>]*>', '<meta property="og:url" content="' + $newsCanonical + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+name=["'']twitter:title["''][^>]*>', '<meta name="twitter:title" content="' + (E $newsTitle) + '">', 1)
$newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+name=["'']twitter:description["''][^>]*>', '<meta name="twitter:description" content="' + (E $newsDescription) + '">', 1)
if ($newsHtml -match '(?is)<meta\s+property=["'']og:image["'']') { $newsHtml = [regex]::Replace($newsHtml, '(?is)<meta\s+property=["'']og:image["''][^>]*>', '<meta property="og:image" content="' + $newsImage + '">', 1) } else { $newsHtml = $newsHtml -replace '</title>', ('</title><meta property="og:image" content="' + $newsImage + '">') }
$newsHtml = [regex]::Replace($newsHtml, '(?s)<script type="application/ld\+json"(?:\s+class="[^"]*")?>.*?</script>', '')
$newsHtml = [regex]::Replace($newsHtml, '(?im)^\s*<link rel="alternate" hreflang=[^>]+>\s*', '')
$newsHtml = [regex]::Replace($newsHtml, '(?im)^\s*<link rel=["''](?:pingback|EditURI|https://api\.w\.org/)["''][^>]*>\s*', '')
$newsHtml = [regex]::Replace($newsHtml, '(?im)^\s*<link rel=["'']alternate["''][^>]+(?:rss\+xml|application/json)[^>]*>\s*', '')
$newsHtml = [regex]::Replace($newsHtml, '(?im)^\s*<meta name="generator"[^>]*>\s*', '')
$itemPosition = 0
$items = @($Pages | Where-Object IsArticle | ForEach-Object { $itemPosition++; [ordered]@{'@type'='ListItem';position=$itemPosition;url=$Domain+$_.Slug+'.html';name=$_.Title} })
$newsSchema = [ordered]@{'@context'='https://schema.org';'@graph'=@(
    [ordered]@{'@type'='Organization';'@id'=$Domain+'#organization';name='789Club';url=$Domain;email='789clubhotorg@gmail.com';telephone='099.58.57.600'},
    [ordered]@{'@type'='WebSite';'@id'=$Domain+'#website';url=$Domain;name='789Club';inLanguage='vi-VN';publisher=[ordered]@{'@id'=$Domain+'#organization'}},
    [ordered]@{'@type'='BreadcrumbList';'@id'=$newsCanonical+'#breadcrumb';itemListElement=@([ordered]@{'@type'='ListItem';position=1;name='Trang chủ';item=$Domain},[ordered]@{'@type'='ListItem';position=2;name='Tin tức';item=$newsCanonical})},
    [ordered]@{'@type'='CollectionPage';'@id'=$newsCanonical+'#collection';url=$newsCanonical;name=$newsTitle;description=$newsDescription;inLanguage='vi-VN';isPartOf=[ordered]@{'@id'=$Domain+'#website'};mainEntity=[ordered]@{'@type'='ItemList';numberOfItems=$items.Count;itemListElement=$items}}
)} | ConvertTo-Json -Depth 12 -Compress
$newsHtml = $newsHtml -replace '</head>', ('<script type="application/ld+json">' + $newsSchema + '</script></head>')
[IO.File]::WriteAllText($newsPath, $newsHtml, $Utf8)

"Đã tối ưu $($Pages.Count) trang nội dung và trang danh mục Tin tức."
